import React, { useState, useEffect } from "react";

export default function UserProfileCard({ token, me = {}, activities = [], setMsg }) {
  const [profile, setProfile] = useState(me);

  // Default avatar image
  const defaultAvatar =
    "https://cdn-icons-png.flaticon.com/512/149/149071.png";

  useEffect(() => {
    if (profile.name) return; // Already have data from props

    if (!token) return;

    const fetchProfile = async () => {
      try {
        const res = await fetch(
          (process.env.REACT_APP_API || "http://localhost:4000") + "/api/ngo/info",
          { headers: { Authorization: `Bearer ${token}` } }
        );
        const data = await res.json();

        if (data.id) {
          setProfile({
            name: data.name,
            email: data.email,
            role: "NGO",
            profileImage: data.profileImage || "",
          });
        } else {
          setMsg && setMsg("Unable to fetch NGO profile");
        }
      } catch (e) {
        console.error("Profile fetch error:", e);
        setMsg && setMsg("Error fetching profile");
      }
    };

    fetchProfile();
  }, [token, profile.name, setMsg]);

  return (
    <div
      style={{
        background: "#fff",
        padding: 16,
        borderRadius: 10,
        textAlign: "center",
        boxShadow: "0 4px 12px rgba(0,0,0,0.05)",
      }}
    >
      {/* Profile Icon */}
      <div
        style={{
          width: 70,
          height: 70,
          borderRadius: "50%",
          overflow: "hidden",
          margin: "0 auto 10px",
        }}
      >
        <img
          src={profile.profileImage || defaultAvatar}
          alt="Profile"
          style={{ width: "100%", height: "100%", objectFit: "cover" }}
        />
      </div>

      <div style={{ fontWeight: "bold", fontSize: 16 }}>{profile.name || "No Name"}</div>
      <div style={{ fontSize: 13, color: "#666", marginBottom: 4 }}>{profile.email || "No Email"}</div>
      <div style={{ fontSize: 13, color: "#666", marginBottom: 8 }}>Role: {profile.role || "Member"}</div>

      {/* Activities */}
      <div style={{ textAlign: "left", marginTop: 10 }}>
        <strong>Activities Participated</strong>
        {activities?.length > 0 ? (
          activities.map((ev) => (
            <div
              key={ev.id}
              style={{ padding: 6, borderBottom: "1px solid #f0f0f0", fontSize: 12 }}
            >
              {ev.title} — {ev.type}
            </div>
          ))
        ) : (
          <div style={{ fontSize: 12, color: "#888" }}>No activities participated yet.</div>
        )}
      </div>
    </div>
  );
}
